        normalized_stage = ConversationSession(customer_id=customer_id, workflow_stage=workflow_stage).workflow_stage
    row = await db.fetch_one(
        """
        INSERT INTO conversation_sessions (customer_id, active_agent, active_intent, workflow_stage, last_route_confidence)
        VALUES (:customer_id, :active_agent, :active_intent, COALESCE(:workflow_stage, 'idle'), :last_route_confidence)
        ON CONFLICT (customer_id) DO UPDATE
        SET active_agent = :active_agent,
            active_intent = :active_intent,
            workflow_stage = COALESCE(:workflow_stage, conversation_sessions.workflow_stage),
            last_route_confidence = :last_route_confidence,
            updated_at = NOW()
        RETURNING customer_id, active_agent, active_intent, workflow_stage, checkout_draft,
                  current_order_id, last_route_confidence, created_at, updated_at
        """,
        {
            "customer_id": customer_id,
            "active_agent": normalized_agent,
            "active_intent": (active_intent or "").strip() or None,
            "workflow_stage": normalized_stage,
            "last_route_confidence": last_route_confidence,
        },
    )
    logger.info(
        "AI workflow transition",
        extra={"active_agent": normalized_agent, "workflow_stage": normalized_stage, "active_intent": active_intent},
    )
    return _row_to_session(row)


async def set_workflow_stage(customer_id: str, workflow_stage: str) -> ConversationSession:
    customer_id = _customer_id_text(customer_id)

"""
OpenAI provider implementation.
Translates the unified interface into openai SDK calls.
"""

import json
import logging

from openai import AsyncOpenAI

from app.ai.providers.base import LLMProvider, LLMResponse

logger = logging.getLogger(__name__)


class OpenAIProvider(LLMProvider):
    def __init__(self, api_key: str):
        self.client = AsyncOpenAI(api_key=api_key)

    # ── Main chat call ───────────────────────────────────────

    async def chat(
        self,
        model: str,
        system_prompt: str,
        messages: list[dict],
        tools: list[dict] | None = None,
        temperature: float = 0.7,
        max_tokens: int = 500,
    ) -> LLMResponse:

        # OpenAI expects the system prompt as the first message
        full_messages = [{"role": "system", "content": system_prompt}] + messages

        kwargs = {
            "model": model,
            "messages": full_messages,
            "temperature": temperature,
            "max_completion_tokens": max_tokens,
        }

        if tools:
            kwargs["tools"] = self._convert_tools(tools)
            kwargs["tool_choice"] = "auto"

        response = await self.client.chat.completions.create(**kwargs)
        return self._normalize(response)

    # ── Continue after tool execution ────────────────────────

    async def continue_after_tool(
        self,
        model: str,
        system_prompt: str,
        messages: list[dict],
        tool_call_id: str,
        tool_name: str,
        tool_result: str,
        tools: list[dict] | None = None,
        temperature: float = 0.7,
        max_tokens: int = 500,
    ) -> LLMResponse:

        full_messages = [{"role": "system", "content": system_prompt}] + messages

        # Append the assistant's tool_call message
        full_messages.append({
            "role": "assistant",
            "tool_calls": [{
                "id": tool_call_id,
                "type": "function",
                "function": {"name": tool_name, "arguments": "{}"},
            }],
        })

        # Append the tool result
        full_messages.append({
            "role": "tool",
            "tool_call_id": tool_call_id,
            "content": tool_result,
        })

        kwargs = {
            "model": model,
            "messages": full_messages,
            "temperature": temperature,
            "max_completion_tokens": max_tokens,
        }

        if tools:
            kwargs["tools"] = self._convert_tools(tools)
            kwargs["tool_choice"] = "auto"

        response = await self.client.chat.completions.create(**kwargs)
        return self._normalize(response)

    # ── Internal helpers ─────────────────────────────────────

    def _convert_tools(self, tools: list[dict]) -> list[dict]:
        """
        Convert our universal tool format to OpenAI's format.
        Universal: {"name", "description", "parameters"}
        OpenAI:    {"type": "function", "function": {"name", "description", "parameters"}}
        """
        return [
            {
                "type": "function",
                "function": {
                    "name": t["name"],
                    "description": t["description"],
                    "parameters": t["parameters"],
                },
            }
            for t in tools
        ]

    def _normalize(self, response) -> LLMResponse:
        """Convert OpenAI's response into our unified LLMResponse."""
        choice = response.choices[0]
        tool_calls = None

        if choice.message.tool_calls:
            tool_calls = []
            for tc in choice.message.tool_calls:
                try:
                    args = json.loads(tc.function.arguments)
                except json.JSONDecodeError:
                    args = {}
                tool_calls.append({
                    "id": tc.id,
                    "name": tc.function.name,
                    "arguments": args,
                })

        return LLMResponse(
            text=choice.message.content,
            tool_calls=tool_calls,
            usage={
                "input_tokens": response.usage.prompt_tokens,
                "output_tokens": response.usage.completion_tokens,
            },
            raw_response=response,
        )

    # ── Vision ───────────────────────────────────────────────

    async def analyze_image(
        self,
        model: str,
        image_base64: str,
        media_type: str,
        prompt: str,
        max_tokens: int = 300,
    ) -> LLMResponse:
        """Analyze an image using OpenAI's vision capability."""
        response = await self.client.chat.completions.create(
            model=model,
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": prompt},
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": f"data:{media_type};base64,{image_base64}",
                                "detail": "low",  # Save tokens; payment screenshots don't need high detail
                            },
                        },
                    ],
                }
            ],
            max_completion_tokens=max_tokens,
        )
        return self._normalize(response)

"""
Anthropic provider implementation.
Translates the unified interface into anthropic SDK calls.

Key differences from OpenAI:
- System prompt is a separate `system` parameter, not a message
- Tool definitions use `input_schema` instead of `parameters`
- Response content is a list of blocks (text, tool_use) instead of a single message
- Tool results use role "user" with a tool_result content block
"""

import logging

from anthropic import AsyncAnthropic

from app.ai.providers.base import LLMProvider, LLMResponse

logger = logging.getLogger(__name__)


class AnthropicProvider(LLMProvider):
    def __init__(self, api_key: str):
        self.client = AsyncAnthropic(api_key=api_key)

    # ── Main chat call ───────────────────────────────────────

    async def chat(
        self,
        model: str,
        system_prompt: str,
        messages: list[dict],
        tools: list[dict] | None = None,
        temperature: float = 0.7,
        max_tokens: int = 500,
    ) -> LLMResponse:

        kwargs = {
            "model": model,
            "system": system_prompt,
            "messages": messages,
            "max_tokens": max_tokens,
            "temperature": temperature,
        }

        if tools:
            kwargs["tools"] = self._convert_tools(tools)
            kwargs["tool_choice"] = {"type": "auto"}

        response = await self.client.messages.create(**kwargs)
        return self._normalize(response)

    # ── Continue after tool execution ────────────────────────

    async def continue_after_tool(
        self,
        model: str,
        system_prompt: str,
        messages: list[dict],
        tool_call_id: str,
        tool_name: str,
        tool_result: str,
        tools: list[dict] | None = None,
        temperature: float = 0.7,
        max_tokens: int = 500,
    ) -> LLMResponse:

        # Anthropic expects the assistant's tool_use block followed by
        # a user message containing the tool_result block
        extended_messages = messages + [
            {
                "role": "assistant",
                "content": [
                    {
                        "type": "tool_use",
                        "id": tool_call_id,
                        "name": tool_name,
                        "input": {},
                    }
                ],
            },
            {
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_call_id,
                        "content": tool_result,
                    }
                ],
            },
        ]

        kwargs = {
            "model": model,
            "system": system_prompt,
            "messages": extended_messages,
            "max_tokens": max_tokens,
            "temperature": temperature,
        }

        if tools:
            kwargs["tools"] = self._convert_tools(tools)
            kwargs["tool_choice"] = {"type": "auto"}

        response = await self.client.messages.create(**kwargs)
        return self._normalize(response)

    # ── Vision ───────────────────────────────────────────────

    async def analyze_image(
        self,
        model: str,
        image_base64: str,
        media_type: str,
        prompt: str,
        max_tokens: int = 300,
    ) -> LLMResponse:
        """Analyze an image using Anthropic's vision capability."""
        response = await self.client.messages.create(
            model=model,
            messages=[
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image",
                            "source": {
                                "type": "base64",
                                "media_type": media_type,
                                "data": image_base64,
                            },
                        },
                        {"type": "text", "text": prompt},
                    ],
                }
            ],
            max_tokens=max_tokens,
        )
        return self._normalize(response)

    # ── Internal helpers ─────────────────────────────────────

    def _convert_tools(self, tools: list[dict]) -> list[dict]:
        """
        Convert our universal tool format to Anthropic's format.
        Universal:  {"name", "description", "parameters"}
        Anthropic:  {"name", "description", "input_schema"}
        """
        return [
            {
                "name": t["name"],
                "description": t["description"],
                "input_schema": t["parameters"],
            }
            for t in tools
        ]

    def _normalize(self, response) -> LLMResponse:
        """Convert Anthropic's response into our unified LLMResponse."""
        text_parts = []
        tool_calls = []

        for block in response.content:
            if block.type == "text":
                text_parts.append(block.text)
            elif block.type == "tool_use":
                tool_calls.append({
                    "id": block.id,
                    "name": block.name,
                    "arguments": block.input,
                })

        return LLMResponse(
            text="\n".join(text_parts) if text_parts else None,
            tool_calls=tool_calls if tool_calls else None,
            usage={
                "input_tokens": response.usage.input_tokens,
                "output_tokens": response.usage.output_tokens,
            },
            raw_response=response,
        )

            fallback_model = settings.get("fallback_model", "claude-haiku-4-5")
            try:
                fallback_provider = self._get_provider(fallback_name)
                response = await fallback_provider.continue_after_tool(model=fallback_model, **kwargs)
                logger.info("Tool continuation fell back to %s/%s", fallback_name, fallback_model)
                return fallback_name, fallback_model, fallback_provider, True, response
            except Exception as exc:
                logger.error("Fallback provider continuation failed for %s/%s: %s", fallback_name, fallback_model, exc)

        return (
            provider_name,
            model,
            provider,
            True,
            LLMResponse(text=_committed_tool_fallback_text(last_tool_name, last_tool_result)),
        )

    async def _initial_response(
        self,
        agent: AgentDefinition,
        system_prompt: str,
        messages: list[dict],
        settings: dict,
    ):
        provider_name = settings.get("llm_provider", "openai")
        model = settings.get("llm_model", "gpt-5.4-nano")
        available = self._list_providers()

        if provider_name not in available:
            if not available:
                raise RuntimeError("No LLM providers are configured.")
            old_name = provider_name
            provider_name = available[0]
            logger.warning(f"Provider '{old_name}' not available, falling back to '{provider_name}'")
            model = next(
                (m["id"] for m in AVAILABLE_MODELS.get(provider_name, []) if m.get("default")),
                "gpt-5.4-nano",
            )

        provider = self._get_provider(provider_name)
        tool_schemas = get_tool_schemas(agent.tool_names)

        try:
            response = await provider.chat(
                model=model,
                system_prompt=system_prompt,
                messages=messages,
                tools=tool_schemas,
                temperature=_temperature(settings, agent),
                max_tokens=settings.get("llm_max_tokens", 500),
            )
            return provider_name, model, provider, False, response
        except Exception as e:
            logger.error(f"Primary provider ({provider_name}) failed: {e}")
            if not settings.get("auto_fallback", True):
                raise

        fallback_name = settings.get("fallback_provider", "anthropic")
        fallback_model = settings.get("fallback_model", "claude-haiku-4-5")
        logger.info(f"Falling back to {fallback_name}/{fallback_model}")
        fallback_provider = self._get_provider(fallback_name)
        response = await fallback_provider.chat(
            model=fallback_model,
            system_prompt=system_prompt,
            messages=messages,
            tools=tool_schemas,
            temperature=_temperature(settings, agent),
            max_tokens=settings.get("llm_max_tokens", 500),
        )
        return fallback_name, fallback_model, fallback_provider, True, response


def format_tool_result_for_model(tool_name: str, result: dict) -> str:
    """Format an internal tool result so the model does not expose raw JSON."""
    return (
        "RESULTADO INTERNO DE HERRAMIENTA. NO lo muestres ni lo cites al cliente.\n"
        f"Herramienta: {tool_name}\n"
        "Usa estos datos solo para redactar una respuesta natural en español.\n"
        f"{json.dumps(result, ensure_ascii=False)}"
    )


def clean_assistant_reply_text(text: str, catalog: list[dict[str, Any]] | None = None) -> str:
    """Remove technical leaks and catalog SKUs from customer-facing replies."""
    cleaned = sanitize_customer_facing_text(text)
    cleaned = strip_catalog_skus_from_text(cleaned, catalog=catalog)
    return cleaned.strip()


def strip_catalog_skus_from_text(text: str, catalog: list[dict[str, Any]] | None = None) -> str:
    """Strip catalog SKUs and parent SKUs from customer-facing text."""
    cleaned = text or ""
    catalog = catalog if catalog is not None else get_cached_catalog() or []
    sku_values = {
        str(product.get("sku", "")).strip()
        for product in catalog
        if str(product.get("sku", "")).strip()
    }
    sku_values.update(
        str(product.get("parent_sku", "")).strip()
        for product in catalog
        if str(product.get("parent_sku", "")).strip()
    )

    for sku in sorted(sku_values, key=len, reverse=True):
        pattern = re.compile(rf"(?i)(?:\(?\b{re.escape(sku)}\b\)?)")
        cleaned = pattern.sub("", cleaned)

    cleaned = re.sub(r"\(\s*\)", "", cleaned)
    cleaned = re.sub(r"\s{2,}", " ", cleaned)
    cleaned = re.sub(r"\s+([,.;:!?])", r"\1", cleaned)
    return cleaned.strip()


def _temperature(settings: dict, agent: AgentDefinition) -> float:
    if settings.get("llm_temperature") is not None:
        return settings.get("llm_temperature", 0.7)
    if agent.default_temperature is not None:
        return agent.default_temperature
    return 0.7


def _resolve_reply_text(
    response_text: str | None,
    interactive_payload: dict | None,
    product_image_payload: dict | None,
) -> str:
    if not response_text and interactive_payload:
        reply_text = interactive_payload.get("body_text", "")
    elif not response_text and product_image_payload:
        reply_text = product_image_payload.get("caption") or "Aquí tienes la foto del producto."
    else:
        reply_text = response_text or DEFAULT_FALLBACK_TEXT
    return clean_assistant_reply_text(reply_text) or DEFAULT_FALLBACK_TEXT


def _empty_usage() -> dict[str, int]:
    return {"input_tokens": 0, "output_tokens": 0}


def _add_usage(target: dict[str, int], usage: dict | None) -> None:
    source = usage or {}
    target["input_tokens"] += int(source.get("input_tokens", 0) or 0)
    target["output_tokens"] += int(source.get("output_tokens", 0) or 0)

