                   AND platform_id = :platform_id
                   AND id <> :id
                 LIMIT 1
                 """,
                 {
                     "channel": channel,
                     "platform_id": row["platform_id"],
                     "id": row["id"],
                 },
             )
             if conflict:
                 raise HTTPException(
