   });
   if (!resp.ok) {
     const data = await resp.json().catch(() => ({}));
     toast(data.detail || 'Error actualizando consentimiento', '#dc2626');
     return;
   }

   const payload = await resp.json().catch(() => ({}));
   Object.assign(customer, payload.customer || {marketing_opt_in: marketingOptIn});
