     <th class="sortable" onclick="sortOrders('status')">Estado pago${sortArrow('orders','status')}</th>
     <th class="sortable" onclick="sortOrders('date')">Fecha${sortArrow('orders','date')}</th>
     <th></th>
   </tr></thead><tbody>`;
   for (const o of orders) {
