       <td>${b.recipients || 0}</td>
       <td><span class="badge ${statusBadge}">${escapeHtml(b.status)}</span></td>
       <td>${sendBtn}</td>
     </tr>`;
   }
   html += '</tbody></table>';
   document.getElementById('broadcasts-list').innerHTML = html;
