async function saveStorePhoneSetting() {
  const phoneInput = document.getElementById('set-store-phone-number');
  const phone = phoneInput?.value?.replace(/\s+/g, ' ').trim() || '';

  if (phone && (!/[0-9]/.test(phone) || !/^[+0-9 ().-]+$/.test(phone) || phone.length > 40)) {
